from pathlib import Path
import subprocess,json,datetime
root=Path('/scratch/alpine/paco0228/ACE/results/ace_llm_intervention_staged_runtime_20261107_01')
r={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
for name,cmd in {'job':['scontrol','show','job','-o','35343957'],'accounting':['sacct','-j','35343957','-n','-P','--format=JobIDRaw,JobID,JobName%60,State,ExitCode,AllocCPUS,ElapsedRaw,Account,AllocTRES%150,MaxRSS,TotalCPU']}.items():
 p=subprocess.run(cmd,capture_output=True,text=True,timeout=15);r[name]={'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
r['packed_files']={str(p.relative_to(root)):p.stat().st_size for p in (root/'qualification/packed').glob('*') if p.is_file()}
r['phases']={str(p.relative_to(root)):json.loads(p.read_bytes()) for p in (root/'qualification').glob('phase-*.json')}
